/**
 * Client-safe household constants. This module must stay free of server-only
 * imports (prisma, next/server, …) so it can be bundled into client components.
 */

/**
 * Canonical House ID format. HIDs are auto-generated by the server and always
 * follow the `106-90-<NNN>` scheme (see `generateNextHID`).
 */
export const HOUSEHOLD_HID_REGEX = /^106-90-\d{3,}$/;

/**
 * Strict house-number family pattern. Only these families may ever exist:
 *   - Staff houses: `SA`–`SE` + digits (e.g. SA1, SE12)
 *   - Category houses: `A`–`E` + digits (e.g. A1, E5)
 * Anything else (F1, G-1, P1, AB1, SA, S1, 123, …) is rejected.
 */
export const HOUSE_NUMBER_FAMILY_REGEX = /^(?:S[A-E]|[A-E])\d+$/i;

/**
 * Valid house types and staff categories. Kept in sync with `validation.ts`.
 */
export const HOUSE_TYPES = ["Staff", "A", "B", "C", "D", "E"] as const;
export const STAFF_CATEGORIES = ["A", "B", "C", "D", "E"] as const;
export const RG_TYPES = ["Regular", "Guest"] as const;

/**
 * House Register import modes. Client-safe so the import wizard can render the
 * selector without importing any server-only module.
 */
export type HouseholdImportMode = "add" | "update" | "add_update";

export const HOUSEHOLD_IMPORT_MODES: readonly {
  value: HouseholdImportMode;
  label: string;
  description: string;
}[] = [
  {
    value: "add",
    label: "Add New Houses",
    description: "Only create houses that do not already exist in the register.",
  },
  {
    value: "update",
    label: "Update Existing Houses",
    description:
      "Only update houses that already exist. Needs the Edit Houses permission.",
  },
  {
    value: "add_update",
    label: "Add + Update",
    description:
      "Create new houses and update existing ones in the same run. Needs the Edit Houses permission.",
  },
];

/**
 * Returns the expected house-number prefix for a house type + staff category,
 * or `null` when the combination is invalid.
 *   Staff + A → "SA", Staff + B → "SB", …, Staff + E → "SE"
 *   A → "A", B → "B", C → "C", D → "D", E → "E"
 */
export function getExpectedHouseNumberPrefix(
  houseType: string,
  staffCategory?: string | null,
): string | null {
  const trimmed = houseType.trim();
  if (trimmed.toLowerCase() === "staff") {
    if (!staffCategory) return null;
    const cat = staffCategory.trim().toUpperCase();
    return (STAFF_CATEGORIES as readonly string[]).includes(cat)
      ? `S${cat}`
      : null;
  }
  const upper = trimmed.toUpperCase();
  return (HOUSE_TYPES as readonly string[]).includes(upper) && upper !== "STAFF"
    ? upper
    : null;
}